import Foundation

/// A city from the bundled list: one of ~75,000 places from GeoNames, with size and capital
/// status. Generated by Tools/GeoPipeline (`--cities`).
struct KnownCity: Decodable, Sendable, Equatable {
    /// English name.
    let name: String
    let nameRu: String?
    /// Native, older and plain-Latin spellings ("Roma", "Алма-Ата"); only searched.
    let aliases: [String]
    /// First-level region, to tell same-named cities in one country apart.
    let region: String?
    let regionRu: String?
    var countryCode: String
    let latitude: Double
    let longitude: Double
    let population: Int
    let isCapital: Bool

    init(
        name: String, nameRu: String?, aliases: [String] = [], region: String?, regionRu: String? = nil,
        countryCode: String, latitude: Double, longitude: Double, population: Int, isCapital: Bool
    ) {
        self.name = name
        self.nameRu = nameRu
        self.aliases = aliases
        self.region = region
        self.regionRu = regionRu
        self.countryCode = countryCode
        self.latitude = latitude
        self.longitude = longitude
        self.population = population
        self.isCapital = isCapital
    }

    private enum CodingKeys: String, CodingKey {
        case name, nameRu, aliases, region, regionRu, population
        case countryCode = "code"
        case latitude = "lat"
        case longitude = "lon"
        case isCapital = "capital"
    }

    /// The name in the first of `languages` the list has, else English. A place without a
    /// Russian name keeps its own in Latin letters: machine transliteration would make
    /// "Bordeaux" into "Бордеаукс".
    func name(in languages: [String]) -> String {
        for language in languages {
            if language.hasPrefix("ru"), let nameRu { return nameRu }
            if language.hasPrefix("en") { return name }
        }
        return name
    }

    /// The region, the same way as `name(in:)`.
    func region(in languages: [String]) -> String? {
        for language in languages {
            if language.hasPrefix("ru"), let regionRu { return regionRu }
            if language.hasPrefix("en") { return region }
        }
        return region
    }

    var draft: CityDraft {
        CityDraft(
            name: name(in: Locale.preferredLanguages),
            region: region(in: Locale.preferredLanguages) ?? "",
            countryCode: countryCode,
            latitude: latitude,
            longitude: longitude
        )
    }
}

/// The bundled city list: instant, offline city search ranked by how well the name matches
/// and then by size (London, UK before London, Kentucky), and the capitals. It's also the
/// reference other sources are matched against, so one city shows once, under the name the
/// app's language gives it.
///
/// The cities stay in their file (`CityTable`) and become `KnownCity` values only when
/// they're asked for, a screenful at a time: opening the list costs one decompression,
/// and a search, a binary search over the name keys.
struct CityCatalog: Sendable {
    private let table: CityTable
    /// Cities on disputed land, given to the country the globe shows there.
    private let moved: [Int: String]
    /// Indices of the capitals.
    private let capitals: [Int]
    /// Size, raised by fame: every four languages that name a place count as doubling it.
    /// Rome, Italy before Rome, Georgia; Amalfi on its coast before the bigger one in
    /// Colombia. Worked out once, since search compares it thousands of times.
    private let prominence: [Float]

    init(_ cities: [KnownCity]) {
        let rows = cities.map { city in
            CityTable.Row(
                name: city.name, nameRu: city.nameRu, aliases: city.aliases,
                region: city.region.map { CityTable.Region(name: $0, nameRu: city.regionRu) },
                countryCode: city.countryCode, latitude: city.latitude, longitude: city.longitude,
                population: city.population, isCapital: city.isCapital
            )
        }
        // Encoded right here, so it always reads back.
        self.init(table: try! CityTable(compressed: CityTable.encode(rows)))
    }

    private init(table: CityTable, moved: [Int: String] = [:]) {
        self.table = table
        self.moved = moved
        capitals = (0..<table.count).filter(table.isCapital)
        prominence = (0..<table.count).map { Float(table.population($0)) * exp2(Float(table.fame($0)) / 4) }
    }

    private init(_ catalog: CityCatalog, moved: [Int: String]) {
        table = catalog.table
        self.moved = moved
        capitals = catalog.capitals
        prominence = catalog.prominence
    }

    /// How many cities there are.
    var count: Int { table.count }

    /// Every capital.
    var capitalCities: [KnownCity] { capitals.map(city) }

    /// A name boiled down so that spellings and scripts meet (`CityKey`): "Алматы" and
    /// "Almaty" are both "almati".
    static func key(_ name: String) -> String { CityKey.key(name) }

    /// The same cities with disputed land given to its owner in the globe's worldview
    /// (`WorldGeometry.owner(at:)`): Simferopol is Ukraine's by default, Russia's in Russia's
    /// App Store.
    func relabeled(by owner: (GeoCoordinate) -> String?) -> CityCatalog {
        var moved: [Int: String] = [:]
        for index in 0..<table.count {
            let coordinate = GeoCoordinate(latitude: table.latitude(index), longitude: table.longitude(index))
            if let code = owner(coordinate), code != table.countryCode(index) { moved[index] = code }
        }
        return moved == self.moved ? self : CityCatalog(self, moved: moved)
    }

    /// The bundled cities in a country that go by `name`, in any spelling or script.
    func cities(named name: String, in countryCode: String) -> [KnownCity] {
        indices(named: name)
            .filter { country(of: $0) == countryCode }
            .sorted { table.population($0) > table.population($1) }
            .map(city)
    }

    /// The bundled city a saved one is: one of its names nearby, or else anything right on
    /// top of it (see `CityMath`). Its name then follows the app's language. The name comes
    /// first: Paris saved by the Hôtel de Ville is Paris, not the arrondissement listed there.
    func city(named name: String, in countryCode: String, latitude: Double, longitude: Double) -> KnownCity? {
        // Within a degree there's room for `sameNameKm` anywhere but the poles: a cheap test
        // before the real distance.
        let near = indices(in: countryCode).filter {
            abs(table.latitude($0) - latitude) < 1 && abs(table.longitude($0) - longitude) < 1.5
        }
        guard !near.isEmpty else { return nil }
        let named = Set(indices(named: name))
        let candidates = near
            .map { (index: $0, km: CityMath.distanceKm(latitude, longitude, table.latitude($0), table.longitude($0))) }
        let sameName = candidates.filter { $0.km < CityMath.sameNameKm && named.contains($0.index) }
        let samePlace = candidates.filter { $0.km < CityMath.samePlaceKm }
        return (sameName.isEmpty ? samePlace : sameName)
            .min { $0.km < $1.km }
            .map { city($0.index) }
    }

    /// Loads on first use: a few megabytes to decompress. Touch it early off the main thread
    /// to warm it.
    static let bundled: CityCatalog = {
        do {
            return try loadBundled()
        } catch {
            assertionFailure("cities.nmcity failed to load: \(error)")
            return CityCatalog([])
        }
    }()

    static func loadBundled() throws -> CityCatalog {
        guard let url = Bundle.main.url(forResource: "cities", withExtension: "nmcity") else {
            throw CocoaError(.fileNoSuchFile)
        }
        return CityCatalog(table: try CityTable(compressed: Data(contentsOf: url, options: .mappedIfSafe)))
    }

    /// Best matches first: the whole name, then its start, then the start of a later word
    /// ("York" → "New York"), then names one typo away ("Боравое" → Боровое). Within each,
    /// the more prominent city first (`prominence`). `countryCode` keeps to one country.
    func search(_ query: String, in countryCode: String? = nil, limit: Int = 8) -> [KnownCity] {
        let needle = Array(CityKey.key(query).utf8)
        guard !needle.isEmpty, limit > 0 else { return [] }
        let country = countryCode.flatMap(table.countryIndex)
        // The best `limit` so far, best first. A short query matches thousands of names;
        // keeping only the top few is what keeps every keystroke instant.
        var best: [(tier: Int, score: Float, city: Int)] = []
        func consider(_ city: Int, tier: Int) {
            let score = prominence[city]
            // Most of a long list can't make it: out before anything else.
            if best.count == limit, let worst = best.last, (tier, -score) >= (worst.tier, -worst.score) { return }
            if let index = best.firstIndex(where: { $0.city == city }) {
                guard tier < best[index].tier else { return }
                best.remove(at: index)
            }
            func isBetter(_ other: (tier: Int, score: Float, city: Int)) -> Bool {
                (tier, -score, city) < (other.tier, -other.score, other.city)
            }
            guard best.count < limit || isBetter(best[best.count - 1]) else { return }
            best.insert((tier, score, city), at: best.firstIndex(where: isBetter) ?? best.count)
            if best.count > limit { best.removeLast() }
        }
        func collect(_ key: [UInt8], typo: Bool) {
            table.forEachEntry(withPrefix: key) { city, cityCountry, isLaterWord, isExact in
                if let countryCode {
                    if !moved.isEmpty, let code = moved[city] {
                        guard code == countryCode else { return }
                    } else {
                        guard cityCountry == country else { return }
                    }
                }
                // A name typed whole comes first, once it's more than a letter or two.
                consider(city, tier: typo ? 3 : isLaterWord ? 2 : key.count >= 3 && isExact ? 0 : 1)
            }
        }
        collect(needle, typo: false)
        // A slip of the finger: only once there's enough typed to tell, and nothing found as
        // typed. Otherwise "Борово" would bring every Chorovoda and Boromo along.
        if best.isEmpty, needle.count >= 5 {
            for variant in Self.typos(of: needle) { collect(variant, typo: true) }
        }
        return best.map { city($0.city) }
    }

    /// A country's cities before anything is typed: the capital first (Astana before the
    /// bigger Almaty), then the biggest.
    func cities(in countryCode: String, limit: Int = 50) -> [KnownCity] {
        indices(in: countryCode).prefix(limit).map(city)
    }

    /// How many cities a country has.
    func cityCount(in countryCode: String) -> Int {
        indices(in: countryCode).count
    }

    /// The capital a saved city is, if it's within `km` of one in its country.
    func capital(latitude: Double, longitude: Double, countryCode: String, within km: Double = 25) -> KnownCity? {
        capitals.first { index in
            country(of: index) == countryCode
                && CityMath.distanceKm(latitude, longitude, table.latitude(index), table.longitude(index)) < km
        }
        .map(city)
    }

    func isCapital(_ city: CityPin) -> Bool {
        capital(latitude: city.latitude, longitude: city.longitude, countryCode: city.countryCode) != nil
    }

    // MARK: - Inside

    private func country(of index: Int) -> String {
        moved[index] ?? table.countryCode(index)
    }

    private func city(_ index: Int) -> KnownCity {
        let region = table.region(index)
        return KnownCity(
            name: table.name(index), nameRu: table.nameRu(index), region: region?.name, regionRu: region?.nameRu,
            countryCode: country(of: index), latitude: table.latitude(index), longitude: table.longitude(index),
            population: table.population(index), isCapital: table.isCapital(index)
        )
    }

    /// A country's cities, capital first, then biggest first; with disputed land moved in.
    private func indices(in countryCode: String) -> [Int] {
        let own = table.countries[countryCode].map(Array.init) ?? []
        guard !moved.isEmpty else { return own }
        let movedIn = moved.filter { $0.value == countryCode }.map(\.key)
        return (own.filter { moved[$0] == nil } + movedIn).sorted {
            (table.isCapital($0) ? 0 : 1, -table.population($0), $0) < (table.isCapital($1) ? 0 : 1, -table.population($1), $1)
        }
    }

    /// Every city with this name, in any of its spellings.
    private func indices(named name: String) -> [Int] {
        let key = Array(CityKey.key(name).utf8)
        guard !key.isEmpty else { return [] }
        var found: [Int] = []
        for entry in table.entries(withPrefix: key) where table.entry(entry, isExactly: key) {
            let (index, isLaterWord) = table.entry(entry)
            if !isLaterWord, !found.contains(index) { found.append(index) }
        }
        return found
    }

    /// Keys one typo away from `key`: a letter dropped, doubled up wrong, swapped with the
    /// next one or replaced. Only the letters keys use.
    private static func typos(of key: [UInt8]) -> [[UInt8]] {
        let letters = Array("abcdefghiklmnoprstuvz".utf8)
        var variants: [[UInt8]] = []
        for i in key.indices {
            var dropped = key
            dropped.remove(at: i)
            variants.append(dropped)
            if i + 1 < key.count, key[i] != key[i + 1] {
                var swapped = key
                swapped.swapAt(i, i + 1)
                variants.append(swapped)
            }
            for letter in letters where letter != key[i] {
                var replaced = key
                replaced[i] = letter
                variants.append(replaced)
            }
        }
        for i in 0...key.count {
            for letter in letters {
                var inserted = key
                inserted.insert(letter, at: i)
                variants.append(inserted)
            }
        }
        return variants
    }
}
